// Generated by rgit agent install; changes are overwritten. Remove with: rgit agent uninstall claude
//
// Registers rgit's tools in the session; each runs `rgit tool <name>` in the session folder.
// All git logic lives in the rgit binary; this module only registers and runs.
import type { EngineInterface, Register } from 'claude-code'

// The rgit binary that installed this file; rgit agent install fills it in.
const RGIT: string = "__RGIT__";
const TOOLS_JSON: string = "__TOOLS__";
// A tool may fetch or push, so it gets a longer timeout.
const TOOL_TIMEOUT_MS = 120000

interface ToolDef {
  name: string
  description: string
  inputSchema: Record<string, unknown>
  annotations?: { readOnlyHint?: boolean }
}

const TOOLS: ToolDef[] = TOOLS_JSON.startsWith("[") ? JSON.parse(TOOLS_JSON) : []

// Claude Code lists a mod's tool as `mcp__<plugin>__<name>`, so `git_status` becomes `mcp__rgit__git_status`.
const TOOL_PREFIX = 'mcp__rgit__'
// The read-only tools the model may call without a prompt, next to the mod's registration.
const ALLOWED = new Set(TOOLS.filter(t => t.annotations?.readOnlyHint).map(t => TOOL_PREFIX + t.name))

/** Runs `rgit tool <name>` for a call of `mcp__rgit__<name>`; a failure is a refusal the model reads as an error. */
async function callTool($: EngineInterface, cwd: string | undefined, tool: string, args: Record<string, unknown>) {
  const name = tool.slice(TOOL_PREFIX.length)
  try {
    const r = await $.process.run([RGIT, 'tool', name], { cwd, stdin: JSON.stringify(args), timeoutMs: TOOL_TIMEOUT_MS })
    const text = r.stdout.trim()
    if (r.exitCode !== 0) return { deny: text || `rgit exited with ${r.exitCode}` }
    return { result: text }
  } catch {
    return { deny: 'rgit did not run: check that the rgit command is installed.' }
  }
}

export const register: Register = on => {
  const tools = new Set<string>()
  let cwd: string | undefined

  on('session.start', async ($, e, next) => {
    cwd = e.cwd
    // In parallel: one at a time, 200 registrations hold up the session start.
    await Promise.all(
      TOOLS.map(t =>
        $.tool.register({ name: t.name, description: t.description, inputSchema: t.inputSchema }).then(
          () => tools.add(TOOL_PREFIX + t.name),
          () => undefined,
        ),
      ),
    )
    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    if (!tools.has(e.tool)) return next(e)
    const { tool, tool_use_id: _id, ...args } = e as { tool: string; tool_use_id: string } & Record<string, unknown>
    return callTool($, cwd, tool, args)
  })

  on('tool.check', async ($, e, next) => (ALLOWED.has(e.tool) ? { decision: 'allow' as const } : next(e)))
}
